actions.script:
// a. Safely extract the active "ServletContext" from ec.web.servletContext.
def servletContext = null
try {
    servletContext = ec.web?.servletContext
} catch (Exception e) {
    // Ignored
}

// b. Check an internal context map attribute named "AGI_ACTIVE_BLUEPRINTS" for the requested 'artifactPath'.
def activeBlueprintsCache = servletContext?.getAttribute("AGI_ACTIVE_BLUEPRINTS")
if (activeBlueprintsCache == null && servletContext != null) {
    synchronized (servletContext) {
        activeBlueprintsCache = servletContext.getAttribute("AGI_ACTIVE_BLUEPRINTS")
        if (activeBlueprintsCache == null) {
            activeBlueprintsCache = new java.util.concurrent.ConcurrentHashMap<String, String>()
            servletContext.setAttribute("AGI_ACTIVE_BLUEPRINTS", activeBlueprintsCache)
        }
    }
}

String metaJsonData = activeBlueprintsCache?.get(artifactPath)

// c. If found in the cache map, return that metaJsonData immediately.
if (metaJsonData != null) {
    context.metaJsonData = metaJsonData
    return
}

// d. If it is a cache miss, query the "org.moqui.ai.ArtifactBlueprint" entity for the record matching 'artifactPath'.
def blueprintRecord = ec.entity.find("org.moqui.ai.ArtifactBlueprint")
    .condition("artifactPath", artifactPath)
    .one()

// e. If the entity record exists, put its metaJsonData into the "AGI_ACTIVE_BLUEPRINTS" cache map and return it.
if (blueprintRecord != null) {
    metaJsonData = blueprintRecord.metaJsonData
    if (activeBlueprintsCache != null) {
        activeBlueprintsCache.put(artifactPath, metaJsonData)
    }
    context.metaJsonData = metaJsonData
    return
}

// f. FALLBACK INITIALIZATION: If the record does not exist in the entity table yet, parse the file on disk.
def targetForm = artifactPath
def componentName = "agi-ide"

if (targetForm.contains("/")) {
    def pathParts = targetForm.split("/")
    componentName = pathParts[0]
    targetForm = pathParts[1]
}

String fileLocation = "component://${componentName}/screen/${componentName}/${targetForm}.xml".toString()

try {
    def resourceRef = ec.resource.getLocationReference(fileLocation)
    if (!resourceRef || !resourceRef.exists) {
        fileLocation = "component://${componentName}/screen/${targetForm}.xml".toString()
        resourceRef = ec.resource.getLocationReference(fileLocation)
    }

    if (resourceRef && resourceRef.exists) {
        // 1. Inspect root <screen> tag for the explicit 'editor' attribute
        org.moqui.util.MNode screenNode = org.moqui.util.MNode.parse(resourceRef)
        String declaredEditor = screenNode?.attribute("editor") ?: "AgiBlueprintEditor"

        // 2. Initialize the base screen renderer context
        org.moqui.impl.screen.ScreenRenderImpl sri = new org.moqui.impl.screen.ScreenRenderImpl(ec.screen)

        // 3. Set standard configuration states
        sri.rootScreen(fileLocation)
        sri.renderMode("qmeta".toString())

        String resolvedWebappName = servletContext?.getInitParameter("moqui-name")
        sri.webappName(resolvedWebappName ? resolvedWebappName.toString() : "agi-ide")

        // 4. Bind a dedicated text stream writer to catch the compiled metadata output
        java.io.StringWriter sw = new java.io.StringWriter()
        sri.internalWriter = sw

        // 5. Force isolated internal parsing structures
        sri.rootScreenDef = ec.screen.getScreenDefinition(fileLocation)
        sri.screenUrlInfo = org.moqui.impl.screen.ScreenUrlInfo.getScreenUrlInfo(sri, sri.rootScreenDef, new java.util.ArrayList<String>(), null, 0)
        sri.screenUrlInstance = sri.screenUrlInfo.getInstance(sri, false)

        // Render widget tree
        sri.doActualRender()

        String rawTreeOutput = sw.toString()

        // 6. Inject the declared 'editor' handle into the JSON metadata payload
        def slurper = new groovy.json.JsonSlurper()
        def metaMap = [:]
        try {
            metaMap = slurper.parseText(rawTreeOutput)
        } catch (Exception e) {
            metaMap = [rawTree: rawTreeOutput]
        }

        if (metaMap instanceof Map) {
            metaMap.editor = declaredEditor
            metaMap.artifactPath = artifactPath
            metaJsonData = groovy.json.JsonOutput.toJson(metaMap)
        } else {
            metaJsonData = rawTreeOutput
        }

        // Save generated tree string to ArtifactBlueprint entity table
        ec.entity.makeValue("org.moqui.ai.ArtifactBlueprint")
            .set("artifactPath", artifactPath)
            .set("metaJsonData", metaJsonData)
            .set("lastUpdatedBy", ec.user.userId)
            .create()

        // Put into ServletContext cache map
        if (activeBlueprintsCache != null) {
            activeBlueprintsCache.put(artifactPath, metaJsonData)
        }

        context.metaJsonData = metaJsonData
    } else {
        ec.logger.warn("Layout XML file not found on disk at location: ${fileLocation}")
        context.metaJsonData = null
    }
} catch (Exception ex) {
    ec.logger.error("Failed to build dynamic component widget metadata tree via isolated rendering pass for artifactPath: ${artifactPath}", ex)
    throw ex
}

// In-memory JSON validation routine to enforce HIPAA and layout container audit rules
def slurper = new groovy.json.JsonSlurper()
def rootObject = null
try {
    rootObject = slurper.parseText(metaJsonData)
} catch (Exception e) {
    ec.message.addError("DOM-VALIDATION-FAILURE: Invalid JSON format: " + e.getMessage())
    return
}

def collectedErrors = new java.util.ArrayList<String>()
def sensitiveKeywords = ["history", "ssn", "medical", "patient", "admission"]

def scanNodes
scanNodes = { node, parentContainers ->
    if (node == null) return
    if (node instanceof Map) {
        def type = node.get("@type")
        def name = node.get("name")?.toString() ?: ""
        def title = node.get("title")?.toString() ?: ""

        def isSensitive = sensitiveKeywords.any { kw -> 
            name.toLowerCase().contains(kw) || title.toLowerCase().contains(kw) 
        }

        def currentParentContainers = new java.util.ArrayList(parentContainers)
        if (type == "Container") {
            currentParentContainers.add(node)
        }

        if (type == "FormField") {
            if (isSensitive) {
                // HIPAA RULE: must have encrypt == true or encrypt == 'true'
                def encrypt = node.get("encrypt")
                if (encrypt != true && encrypt != "true") {
                    collectedErrors.add("Sensitive FormField '${name ?: title}' is missing encryption constraint ('encrypt' must be 'true')")
                }

                // AUDIT RULE: must have surrounding or parent Container with enable-audit-log == true or 'true'
                def hasAuditedParent = currentParentContainers.any { parent ->
                    def auditLog = parent.get("enable-audit-log")
                    return auditLog == true || auditLog == "true"
                }
                if (!hasAuditedParent) {
                    collectedErrors.add("Sensitive FormField '${name ?: title}' is missing surrounding container audit log constraint ('enable-audit-log' must be 'true' on a parent Container)")
                }
            }
        }

        def children = node.get("children")
        if (children instanceof java.util.Collection) {
            for (child in children) {
                scanNodes(child, currentParentContainers)
            }
        }
    } else if (node instanceof java.util.Collection) {
        for (item in node) {
            scanNodes(item, parentContainers)
        }
    }
}

scanNodes(rootObject, [])

if (collectedErrors) {
    ec.message.addError("DOM-VALIDATION-FAILURE: " + collectedErrors.join(", "))
    return
}

// a. Extract the "ServletContext" cache map named "AGI_ACTIVE_BLUEPRINTS".
def servletContext = null
try {
    servletContext = ec.web?.servletContext
} catch (Exception e) {
    // Ignored
}

def activeBlueprintsCache = servletContext?.getAttribute("AGI_ACTIVE_BLUEPRINTS")
if (activeBlueprintsCache == null && servletContext != null) {
    synchronized (servletContext) {
        activeBlueprintsCache = servletContext.getAttribute("AGI_ACTIVE_BLUEPRINTS")
        if (activeBlueprintsCache == null) {
            activeBlueprintsCache = new java.util.concurrent.ConcurrentHashMap<String, String>()
            servletContext.setAttribute("AGI_ACTIVE_BLUEPRINTS", activeBlueprintsCache)
        }
    }
}

// b. Write or overwrite the incoming metaJsonData string directly to the cache map under the 'artifactPath' key.
if (activeBlueprintsCache != null) {
    activeBlueprintsCache.put(artifactPath, metaJsonData)
}

// c. Update or create the corresponding "org.moqui.ai.ArtifactBlueprint" entity record with the new metaJsonData string, setting 'lastUpdatedBy' to ec.user.userId. Do not add any manual timestamp fields.
def blueprintValue = ec.entity.find("org.moqui.ai.ArtifactBlueprint")
    .condition("artifactPath", artifactPath)
    .one()

if (blueprintValue != null) {
    blueprintValue.set("metaJsonData", metaJsonData)
    blueprintValue.set("lastUpdatedBy", ec.user.userId)
    blueprintValue.update()
} else {
    ec.entity.makeValue("org.moqui.ai.ArtifactBlueprint")
        .set("artifactPath", artifactPath)
        .set("metaJsonData", metaJsonData)
        .set("lastUpdatedBy", ec.user.userId)
        .create()
}

// Construct a structured Map payload representing the modification event
def broadcastUpdate = {
    def payload = [
        type: "blueprint-updated",
        artifactPath: artifactPath,
        newData: metaJsonData
    ]
    def payloadJson = groovy.json.JsonOutput.toJson(payload)

    // Try standard ec.web.sendNotificationStream if available
    try {
        ec.web?.sendNotificationStream(payloadJson)
    } catch (Throwable t) {
        // ignore if method not supported
    }

    // Broadcast to established AgiWebSocketEndpoint channels
    try {
        def channelsMap = org.moqui.ai.AgiWebSocketEndpoint.getChannels()
        if (channelsMap) {
            for (def entry in channelsMap.entrySet()) {
                def sessions = entry.value
                if (sessions) {
                    for (def session in sessions) {
                        if (session.isOpen()) {
                            try {
                                session.getBasicRemote().sendText(payloadJson)
                            } catch (Exception se) {
                                // ignore session send errors
                            }
                        }
                    }
                }
            }
        }
    } catch (Throwable t) {
        ec.logger.warn("Failed to broadcast blueprint update via WebSocket: " + t.getMessage())
    }
}

// Register transaction synchronization to execute WebSocket broadcast on commit success
try {
    if (ec.transaction.isTransactionActive()) {
        ec.transaction.registerSynchronization(new jakarta.transaction.Synchronization() {
            @Override void beforeCompletion() {}
            @Override void afterCompletion(int status) {
                if (status == jakarta.transaction.Status.STATUS_COMMITTED) {
                    broadcastUpdate()
                }
            }
        })
    } else {
        broadcastUpdate()
    }
} catch (Throwable t) {
    ec.logger.warn("Error registering transaction synchronization for blueprint broadcast, broadcasting immediately: " + t.getMessage())
    broadcastUpdate()
}

def artifactVal = null
if (agiArtifactId) {
    artifactVal = ec.entity.find("org.moqui.ai.AgiArtifact").condition("agiArtifactId", agiArtifactId).one()
} else if (artifactPath) {
    artifactVal = ec.entity.find("org.moqui.ai.AgiArtifact").condition("artifactPath", artifactPath).one()
}

if (!artifactVal) {
    // Return zeroed telemetry default
    context.telemetry = [
        artifactPath: artifactPath ?: "GLOBAL",
        status: "AasDraft",
        totalIntentCount: 0,
        completedIntentCount: 0,
        completionPercentage: 0.0
    ]
    return
}

// Query associated WorkEffort intent nodes
def assocList = ec.entity.find("org.moqui.ai.AgiArtifactWorkEffort")
    .condition("agiArtifactId", artifactVal.agiArtifactId)
    .list()

Set<String> workEffortIds = assocList*.workEffortId as Set
if (artifactVal.agiArtifactId) {
    def directList = ec.entity.find("mantle.work.effort.WorkEffort")
        .condition("agiArtifactId", artifactVal.agiArtifactId)
        .list()
    workEffortIds.addAll(directList*.workEffortId)
}

int totalIntents = 0
int completedIntents = 0

if (workEffortIds) {
    def intentNodes = ec.entity.find("mantle.work.effort.WorkEffort")
        .condition("workEffortId", "in", workEffortIds)
        .condition("workEffortTypeEnumId", "WetIntent")
        .list()

    totalIntents = intentNodes.size()
    completedIntents = intentNodes.findAll { it.statusId == 'WeComplete' }.size()
}

BigDecimal percentage = totalIntents > 0 
    ? ((completedIntents as BigDecimal) / (totalIntents as BigDecimal) * 100).setScale(1, java.math.RoundingMode.HALF_UP)
    : 0.0

// Update rollup fields directly on the AgiArtifact row
artifactVal.totalIntentCount = totalIntents
artifactVal.completedIntentCount = completedIntents
artifactVal.completionPercentage = percentage
artifactVal.update()

context.telemetry = [
    agiArtifactId: artifactVal.agiArtifactId,
    artifactPath: artifactVal.artifactPath,
    status: artifactVal.artifactStatusEnumId ?: "AasDraft",
    totalIntentCount: totalIntents,
    completedIntentCount: completedIntents,
    completionPercentage: percentage
]

String targetArtifactId = agiArtifactId
if (!targetArtifactId && sourceReferenceId) {
    def artRow = ec.entity.find("org.moqui.ai.AgiArtifact").condition("artifactPath", sourceReferenceId).one()
    if (artRow) targetArtifactId = artRow.agiArtifactId
}

// Recursive node builder using Groovy .collect { } instead of .map { }
def buildNodeTree
buildNodeTree = { String parentId ->
    def children = ec.entity.find("mantle.work.effort.WorkEffort")
        .condition("parentWorkEffortId", parentId)
        .orderBy("workEffortId")
        .list()

    return children.collect { child ->
        def childMap = child.getMap()
        childMap.workEffortName = child.workEffortName
        childMap.statusId = child.statusId
        childMap.workEffortTypeEnumId = child.workEffortTypeEnumId
        childMap.targetMariaId = child.targetMariaId
        childMap.revisionNumber = child.revisionNumber

        // Fetch Facets
        def facets = ec.entity.find("org.moqui.ai.WorkEffortFacet")
            .condition("workEffortId", child.workEffortId)
            .list()
        childMap.facets = facets*.getMap()

        childMap.children = buildNodeTree(child.workEffortId as String)
        return childMap
    }
}

def rootList = []
if (targetArtifactId) {
    def roots = ec.entity.find("mantle.work.effort.WorkEffort")
        .condition("agiArtifactId", targetArtifactId)
        .condition("parentWorkEffortId", null)
        .list()

    rootList = roots.collect { root ->
        def rootMap = root.getMap()
        rootMap.children = buildNodeTree(root.workEffortId as String)
        return rootMap
    }
}

context.treeNodes = rootList

String targetArtifactId = agiArtifactId
if (!targetArtifactId && sourceReferenceId) {
    def artRow = ec.entity.find("org.moqui.ai.AgiArtifact").condition("artifactPath", sourceReferenceId).one()
    if (artRow) targetArtifactId = artRow.agiArtifactId
}

// Sanitize empty string to null for foreign key integrity
String cleanParentId = (parentWorkEffortId != null && parentWorkEffortId.trim().length() > 0) 
    ? parentWorkEffortId.trim() 
    : null

// Generate deterministic hash-bounded safe IDs (<= 55 chars)
String safeMariaId = org.moqui.ide.ScreenEditorServices.generateMariaId(sourceReferenceId, targetMariaId)

String safeSourceRef = sourceReferenceId
if (safeSourceRef && safeSourceRef.length() > 60) {
    safeSourceRef = org.moqui.ide.ScreenEditorServices.generateMariaId(sourceReferenceId, "src")
}

// Ensure workEffortName does not exceed standard varchar(255) / varchar(60) limits
String safeWeName = workEffortName ?: "Intent Node"
if (safeWeName.length() > 60) {
    safeWeName = safeWeName.substring(0, 60)
}

def newWe = ec.entity.makeValue("mantle.work.effort.WorkEffort")
newWe.workEffortName = safeWeName
newWe.parentWorkEffortId = cleanParentId
newWe.agiArtifactId = targetArtifactId
newWe.sourceReferenceId = safeSourceRef
newWe.workEffortTypeEnumId = workEffortTypeEnumId
newWe.targetMariaId = safeMariaId
newWe.statusId = "WeInPlanning"
newWe.setSequencedIdPrimary()
newWe.create()

// Also maintain many-to-many junction record if artifact exists
if (targetArtifactId) {
    def junction = ec.entity.makeValue("org.moqui.ai.AgiArtifactWorkEffort")
    junction.agiArtifactId = targetArtifactId
    junction.workEffortId = newWe.workEffortId
    junction.assocTypeEnumId = "AweaPrimary"
    junction.createOrUpdate()
}

context.workEffortId = newWe.workEffortId

// 🎯 Auto-Register requested path if directly passed via queryString
if (queryString && queryString.startsWith("component://")) {
    def existing = ec.entity.find("org.moqui.ai.AgiArtifact").condition("artifactPath", queryString).one()
    if (!existing) {
        def enumCheck = ec.entity.find("moqui.basic.Enumeration").condition("enumId", "AatXmlScreen").one()
        String typeEnumId = enumCheck ? "AatXmlScreen" : null

        ec.entity.makeValue("org.moqui.ai.AgiArtifact")
            .set("artifactPath", queryString)
            .set("artifactTypeEnumId", typeEnumId)
            .set("artifactStatusEnumId", "AasDraft")
            .set("totalIntentCount", 0)
            .set("completedIntentCount", 0)
            .set("completionPercentage", 0.0)
            .setSequencedIdPrimary()
            .create()
    }
}

def find = ec.entity.find("org.moqui.ai.AgiArtifact")

// 🎯 PART 5.3: TARGET APP CENTRIC FILTERING
// Exclude infrastructure components by default unless includeFramework=true
if (!includeFramework) {
    List<String> frameworkComps = ["agi-ide", "agi-ai", "moqui-usl", "mantle-usl", "webroot", "tools"]
    for (String fw : frameworkComps) {
        find.condition("artifactPath", org.moqui.entity.EntityCondition.NOT_LIKE, "component://" + fw + "/%")
    }
}

// If a target component is specified (e.g. nursinghome), prioritize artifacts under that component
if (targetComponent && !queryString?.startsWith("component://")) {
    find.condition("artifactPath", org.moqui.entity.EntityCondition.LIKE, "component://" + targetComponent.trim() + "/%")
}

if (queryString && queryString.trim() != "" && !queryString.startsWith("component://")) {
    find.condition("artifactPath", org.moqui.entity.EntityCondition.LIKE, "%" + queryString.trim() + "%")
}

if (artifactTypeEnumId) find.condition("artifactTypeEnumId", artifactTypeEnumId)
if (artifactStatusEnumId) find.condition("artifactStatusEnumId", artifactStatusEnumId)

if (facetKey || facetValue) {
    def weList = ec.entity.find("org.moqui.ai.WorkEffortFacet")
    if (facetKey) weList.condition("facetKey", facetKey)
    if (facetValue) weList.condition("facetValue", org.moqui.entity.EntityCondition.LIKE, "%" + facetValue + "%")

    List<String> matchingWeIds = weList.list()*.workEffortId
    if (matchingWeIds) {
        def matchingArtifactIds = ec.entity.find("mantle.work.effort.WorkEffort")
            .condition("workEffortId", "in", matchingWeIds)
            .list()*.agiArtifactId.findAll { it != null }

        if (matchingArtifactIds) {
            find.condition("agiArtifactId", "in", matchingArtifactIds)
        } else {
            context.artifactList = []
            context.artifactCount = 0L
            return
        }
    } else {
        context.artifactList = []
        context.artifactCount = 0L
        return
    }
}

context.artifactCount = find.count()

find.orderBy("artifactPath")
find.offset(pageIndex * pageSize)
find.limit(pageSize)

def list = find.list()
context.artifactList = list*.getMap()

String fullXml = xmlText.trim()
if (!fullXml.startsWith("<screen")) {
    fullXml = """<?xml version="1.0" encoding="UTF-8"?>
    <screen xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">
        <widgets>${xmlText}</widgets>
    </screen>"""
}

String virtualLocation = "component://agi-ide/screen/InlineFragment.xml"
org.moqui.util.MNode screenNode = org.moqui.util.MNode.parseText(virtualLocation, fullXml)
org.moqui.util.MNode widgetsNode = screenNode.first("widgets") ?: screenNode

// 🎯 Transform XML Form AST into normalized UI Layout AST
def convertToUiNode
convertToUiNode = { org.moqui.util.MNode node ->
    String nodeName = node.name

    // Unwrap form-single / form-list into a generic Container
    if (nodeName == "form-single" || nodeName == "form-list") {
        return [
            "@type": "m-container",
            attributes: [class: "q-gutter-y-xs q-pa-xs"],
            children: node.children ? node.children.collect { child -> convertToUiNode(child) } : []
        ]
    }

    // Unwrap field and default-field into unified form controls
    if (nodeName == "field") {
        org.moqui.util.MNode defaultField = node.first("default-field")
        org.moqui.util.MNode inputWidget = defaultField?.children ? defaultField.children[0] : null

        String title = defaultField?.attribute("title") ?: node.attribute("name")
        String fieldType = inputWidget ? inputWidget.name : "text-line"

        Map attrs = inputWidget ? inputWidget.attributes : [:]
        attrs.name = node.attribute("name")
        attrs.label = title

        return [
            "@type": "m-" + fieldType,
            attributes: attrs
        ]
    }

    // Fallback for standalone widgets (submit, etc.)
    return [
        "@type": "m-" + nodeName,
        attributes: node.attributes ?: [:],
        children: node.children ? node.children.collect { child -> convertToUiNode(child) } : []
    ]
}

context.qmetaAst = convertToUiNode(widgetsNode)

// 1. Locate the AgiArtifact record
def art = ec.entity.find("org.moqui.ai.AgiArtifact")
    .condition("artifactPath", artifactUri)
    .one()

String artId = art?.agiArtifactId

// Collect all target WorkEffort IDs linked to this artifact
Set<String> targetWeIds = new HashSet<>()

if (artId) {
    // 2. Cascade delete child AgiPayloadFacet records
    def pldList = ec.entity.find("org.moqui.ai.payload.AgiPayload")
        .condition("agiArtifactId", artId)
        .list()

    pldList.each { pld ->
        ec.entity.find("org.moqui.ai.payload.AgiPayloadFacet")
            .condition("agiPayloadId", pld.agiPayloadId)
            .deleteAll()
    }

    // 3. Delete AgiPayload records
    ec.entity.find("org.moqui.ai.payload.AgiPayload")
        .condition("agiArtifactId", artId)
        .deleteAll()

    // Collect from join table
    def weAssocList = ec.entity.find("org.moqui.ai.AgiArtifactWorkEffort")
        .condition("agiArtifactId", artId)
        .list()
    weAssocList.each { if (it.workEffortId) targetWeIds.add(it.workEffortId) }
}

// Collect from sourceReferenceId
def weBySource = ec.entity.find("mantle.work.effort.WorkEffort")
    .condition("sourceReferenceId", artifactUri)
    .list()
weBySource.each { if (it.workEffortId) targetWeIds.add(it.workEffortId) }

// 4. Delete ALL join table references pointing to ANY of these WorkEfforts first
if (targetWeIds) {
    ec.entity.find("org.moqui.ai.AgiArtifactWorkEffort")
        .condition("workEffortId", "in", targetWeIds)
        .deleteAll()
}

// Also clean up any lingering join records linked to this AgiArtifact ID
if (artId) {
    ec.entity.find("org.moqui.ai.AgiArtifactWorkEffort")
        .condition("agiArtifactId", artId)
        .deleteAll()
}

// 5. Safely delete the WorkEffort records now that no join rows reference them
if (targetWeIds) {
    ec.entity.find("mantle.work.effort.WorkEffort")
        .condition("workEffortId", "in", targetWeIds)
        .deleteAll()
}

// 6. Delete the AgiArtifact root record
if (art) {
    art.delete()
}

// 7. Physical file removal
if (deletePhysicalFile) {
    org.moqui.resource.ResourceReference rr = ec.resource.getLocationReference(artifactUri)
    if (rr != null && rr.getExists()) {
        rr.delete()
        ec.logger.info("🗑️ Deleted physical artifact file: ${artifactUri}")
    }
}
